// ==========================================
// 4-Channel 5V Relay: ควบคุมเปิด-ปิดรีเลย์ 4 ช่อง (Active LOW)
// แก้ไขหมายเลขขา CH1_PIN ถึง CH4_PIN ด้านล่างได้ทันที
// ==========================================
#define CH1_PIN 4   // ขาควบคุมรีเลย์ช่อง 1
#define CH2_PIN 5   // ขาควบคุมรีเลย์ช่อง 2
#define CH3_PIN 6   // ขาควบคุมรีเลย์ช่อง 3
#define CH4_PIN 7   // ขาควบคุมรีเลย์ช่อง 4

// นิยามสถานะสำหรับ Active LOW ให้อ่านโค้ดเข้าใจง่าย
#define RELAY_ON  LOW   // สั่งเปิดรีเลย์ด้วยสัญญาณ LOW
#define RELAY_OFF HIGH  // สั่งปิดรีเลย์ด้วยสัญญาณ HIGH

void setup() {
  Serial.begin(9600);

  // กำหนดขาควบคุมทุกช่องให้เป็น Output
  pinMode(CH1_PIN, OUTPUT);
  pinMode(CH2_PIN, OUTPUT);
  pinMode(CH3_PIN, OUTPUT);
  pinMode(CH4_PIN, OUTPUT);

  // เริ่มต้นปิดรีเลย์ทุกช่องไว้ก่อนเพื่อความปลอดภัย
  digitalWrite(CH1_PIN, RELAY_OFF);
  digitalWrite(CH2_PIN, RELAY_OFF);
  digitalWrite(CH3_PIN, RELAY_OFF);
  digitalWrite(CH4_PIN, RELAY_OFF);

  Serial.println("4-Channel Relay Initialized (All Relays OFF)");
}

void loop() {
  // ตัวอย่าง: เปิดรีเลย์ช่อง 1 นาน 2 วินาที แล้วปิด
  Serial.println("Relay CH1 -> ON");
  digitalWrite(CH1_PIN, RELAY_ON);
  delay(2000);
  digitalWrite(CH1_PIN, RELAY_OFF);
  Serial.println("Relay CH1 -> OFF");

  // สลับมาเปิดรีเลย์ช่อง 2 นาน 2 วินาที แล้วปิด
  Serial.println("Relay CH2 -> ON");
  digitalWrite(CH2_PIN, RELAY_ON);
  delay(2000);
  digitalWrite(CH2_PIN, RELAY_OFF);
  Serial.println("Relay CH2 -> OFF");

  delay(1000); // พัก 1 วินาทีก่อนวนรอบใหม่
}
